function checkCommitMessage(message) {
  const text = message.trim();
  if (text === "") return "пустое сообщение";
  if (text.length > 72) return "слишком длинное";
  const vague = ["fix", "update", "changes", "wip", "asdf"];
  if (vague.includes(text.toLowerCase())) return "неинформативное";
  return null;
}

