function resolveConflict(text, side) {
  const result = [];
  let state = "out";
  let ours = [];
  let theirs = [];
  for (const line of text.split("\n")) {
    if (line.startsWith("<<<<<<<")) { state = "ours"; ours = []; theirs = []; continue; }
    if (line === "=======" && state === "ours") { state = "theirs"; continue; }
    if (line.startsWith(">>>>>>>") && state === "theirs") {
      if (side === "ours" || side === "both") result.push(...ours);
      if (side === "theirs" || side === "both") result.push(...theirs);
      state = "out";
      continue;
    }
    if (state === "ours") ours.push(line);
    else if (state === "theirs") theirs.push(line);
    else result.push(line);
  }
  return result.join("\n");
}

