function branchName(type, taskId, title) {
  const safeType = ["feature", "fix", "docs"].includes(type) ? type : "feature";
  const slug = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 30)
    .replace(/-+$/g, "");
  return `${safeType}/${taskId}-${slug}`;
}

